buildReplicaModel: buildReplicaModel
});
})();

(() => {
'use strict';
// shard-runtime

function asRecord(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function asErrorMessage(error) {
  return error instanceof Error ? error.message : String(error || '未知运行时错误');
}

function api(scope, name) {
  if (typeof scope?.[name] === 'function') return scope[name].bind(scope);
  if (typeof scope?.TavernHelper?.[name] === 'function') return scope.TavernHelper[name].bind(scope.TavernHelper);
  return null;
}

function unwrapStatData(value) {
  const root = asRecord(value);
  if (root.stat_data && typeof root.stat_data === 'object') return root.stat_data;
  if (root.data && asRecord(root.data).stat_data && typeof root.data.stat_data === 'object') {
    return root.data.stat_data;
  }
  return null;
}

function eventNames(scope) {
  const names = new Set();
  const mvuEvents = asRecord(scope?.Mvu?.events);
  for (const key of ['VARIABLE_INITIALIZED', 'VARIABLE_UPDATE_ENDED']) {
    if (typeof mvuEvents[key] === 'string') names.add(mvuEvents[key]);
  }
  const tavernEvents = asRecord(scope?.tavern_events);
  for (const key of [
    'CHAT_CHANGED',
    'MESSAGE_UPDATED',
    'MESSAGE_RECEIVED',
    'MESSAGE_SWIPED',
    'CHARACTER_MESSAGE_RENDERED',
    'USER_MESSAGE_RENDERED',
  ]) {
    if (typeof tavernEvents[key] === 'string') names.add(tavernEvents[key]);
  }
  return [...names];
}

function makeDisposer(handle) {
  if (typeof handle === 'function') return handle;
  if (typeof handle?.stop === 'function') return () => handle.stop();
  if (typeof handle?.dispose === 'function') return () => handle.dispose();
  return () => {};
}

function createShardRuntime(scope = globalThis) {
  const readVariables = api(scope, 'getVariables');
  const readMvu = typeof scope?.Mvu?.getMvuData === 'function'
    ? scope.Mvu.getMvuData.bind(scope.Mvu)
    : null;
  const listen = api(scope, 'eventOn');
  let lastGood = null;

  async function read(previous = lastGood) {
    const errors = [];
    if (readVariables) {
      try {
        const result = unwrapStatData(await readVariables({ type: 'message', message_id: 'latest' }));
        if (result) {
          lastGood = result;
          return { status: 'ready', source: 'getVariables', statData: result, message: '' };
        }
        errors.push('getVariables 未返回 stat_data');
      } catch (error) {
        errors.push(`getVariables: ${asErrorMessage(error)}`);
      }
    }
    if (readMvu) {
      try {
        const result = unwrapStatData(await readMvu({ type: 'message', message_id: 'latest' }));
        if (result) {
          lastGood = result;
          return { status: 'ready', source: 'Mvu.getMvuData', statData: result, message: '' };
        }
        errors.push('Mvu.getMvuData 未返回 stat_data');
      } catch (error) {
        errors.push(`Mvu.getMvuData: ${asErrorMessage(error)}`);
      }
    }
    if (previous && typeof previous === 'object') {
      lastGood = previous;
      return {
        status: 'stale',
        source: 'last-good',
        statData: previous,
        message: errors.join('；') || '暂时无法读取最新状态，保留上次成功数据。',
      };
    }
    return {
      status: 'unavailable',
      source: '',
      statData: {},
      message: errors.join('；') || '未检测到 Tavern Helper/MVU 只读接口。',
    };
  }

  function subscribe(listener) {
    if (typeof listener !== 'function' || !listen) return () => {};
    const disposers = [];
    for (const event of eventNames(scope)) {
      try {
        disposers.push(makeDisposer(listen(event, listener)));
      } catch {
        // An optional event can be unavailable in older Tavern Helper builds.
      }
    }
    return () => disposers.splice(0).forEach((dispose) => {
      try { dispose(); } catch {}
    });
  }

  function probe() {
    return Object.freeze({
      tavern: typeof scope?.getTavernVersion === 'function' ? scope.getTavernVersion() : '',
      helper: typeof scope?.getTavernHelperVersion === 'function' ? scope.getTavernHelperVersion() : '',
      hasGetVariables: Boolean(readVariables),
      hasMvu: Boolean(readMvu),
      eventCount: eventNames(scope).length,
    });
  }

  return Object.freeze({
    read,
    subscribe,
    probe,
    ready: async () => {},
    getLastGood: () => lastGood,
  });
}

function discoverShardRuntimeScope(start = globalThis) {
  const candidates = [start];
  try {
    if (start?.parent && start.parent !== start) candidates.push(start.parent);
  } catch {}
  return candidates.find((candidate) => (
    typeof candidate?.getVariables === 'function'
    || typeof candidate?.TavernHelper?.getVariables === 'function'
    || typeof candidate?.Mvu?.getMvuData === 'function'
  )) || start;
}

Object.assign(globalThis.Re0Shard, {
createShardRuntime: createShardRuntime,
discoverShardRuntimeScope: discoverShardRuntimeScope
});
})();

(() => {
'use strict';
// orb-drag

const DRAG_THRESHOLD = 6;

function normalizeOrbPosition(position = {}) {
  const x = Number(position.x);
  const y = Number(position.y);
  return {
    x: Number.isFinite(x) ? Math.min(1, Math.max(0, x)) : 0.82,
    y: Number.isFinite(y) ? Math.min(1, Math.max(0, y)) : 0.5,
  };
}

function distanceBetween(first, second) {
  return Math.hypot(second.clientX - first.startX, second.clientY - first.startY);
}

function createOrbDragController({
  initial = { x: 0.82, y: 0.5 },
  threshold = DRAG_THRESHOLD,
  viewport = () => ({ width: globalThis.innerWidth || 1, height: globalThis.innerHeight || 1 }),
  onStateChange = () => {},
  onPositionChange = () => {},
  onClick = () => {},
} = {}) {
  let position = normalizeOrbPosition(initial);
  let gesture = null;

  const emit = (state) => onStateChange({
    dragging: Boolean(state.dragging),
    pressed: Boolean(state.pressed),
    position: { ...position },
  });

  const pointerDown = (event) => {
    if (!event || gesture || !Number.isFinite(Number(event.pointerId))) return false;
    gesture = {
      pointerId: Number(event.pointerId),
      startX: Number(event.clientX) || 0,
      startY: Number(event.clientY) || 0,
      startPosition: { ...position },
      dragging: false,
    };
    emit({ pressed: true, dragging: false });
    return true;
  };

  const pointerMove = (event) => {
    if (!gesture || Number(event?.pointerId) !== gesture.pointerId) return false;
    if (!gesture.dragging && distanceBetween(gesture, event) > threshold) {
      gesture.dragging = true;
      emit({ pressed: true, dragging: true });
    }
    if (!gesture.dragging) return false;
    const size = viewport() || {};
    const width = Math.max(1, Number(size.width) || 1);
    const height = Math.max(1, Number(size.height) || 1);
    position = normalizeOrbPosition({
      x: gesture.startPosition.x + ((Number(event.clientX) || 0) - gesture.startX) / width,
      y: gesture.startPosition.y + ((Number(event.clientY) || 0) - gesture.startY) / height,
    });
    emit({ pressed: true, dragging: true });
    onPositionChange({ ...position }, { phase: 'drag' });
    return true;
  };

  const finish = (event, cancelled = false) => {
    if (!gesture || Number(event?.pointerId) !== gesture.pointerId) return false;
    const wasDrag = gesture.dragging;
    gesture = null;
    emit({ pressed: false, dragging: false });
    if (cancelled) return true;
    if (wasDrag) onPositionChange({ ...position }, { phase: 'settle' });
    else onClick();
    return true;
  };

  return Object.freeze({
    pointerDown,
    pointerMove,
    pointerUp: (event) => finish(event, false),
    pointerCancel: (event) => finish(event, true),
    getPosition: () => ({ ...position }),
    setPosition: (next) => {
      position = normalizeOrbPosition(next);
      emit({ pressed: false, dragging: false });
    },
    isDragging: () => Boolean(gesture?.dragging),
  });
}

Object.assign(globalThis.Re0Shard, {
DRAG_THRESHOLD: DRAG_THRESHOLD,
normalizeOrbPosition: normalizeOrbPosition,
createOrbDragController: createOrbDragController
});
})();

(() => {
'use strict';
// shard-ui
const { isSafeAssetUrl, resolveCharacterVisual } = globalThis.Re0Shard;

const SLOT_TONES = Object.freeze(['violet', 'cyan', 'gold', 'rose', 'mint', 'blue']);

function element(documentRef, tagName, className = '', text = '') {
  const node = documentRef.createElement(tagName);
  if (className) node.className = className;
  if (text !== '') node.textContent = String(text);
  return node;
}

function button(documentRef, label, action, className = '') {
  const node = element(documentRef, 'button', className, label);
  node.type = 'button';
  node.dataset.action = action;
  return node;
}

function compactText(value, limit = 28) {
  const text = String(value ?? '').replace(/\s+/gu, ' ').trim();
  return text.length > limit ? `${text.slice(0, limit - 1)}…` : text;
}

function setImage(node, url, alt = '') {
  if (!url || !isSafeAssetUrl(url)) return false;
  const image = node.ownerDocument.createElement('img');
  image.src = url;
  image.alt = alt;
  image.loading = 'lazy';
  image.decoding = 'async';
  image.addEventListener('error', () => image.remove(), { once: true });
  node.append(image);
  return true;
}

